// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = function () {
    let __attrReals = [{ childId: "ul_68", attr: "__html", fn: function () { return ([String($c.data.readValue("dma_page", "total", { silent: true })), String($c.data.readValue("dma_page", "currentPage", { silent: true })), String($c.data.readValue("dma_page", "pageCount", { silent: true }))].some(function (__v) { return String(__v == null ? '' : __v).trim() !== ''; }) ? ("총 <strong id=\"totPage\">" + String($c.data.readValue("dma_page", "total", { silent: true })) + "</strong>건 <span id=\"totPage1\">(" + String($c.data.readValue("dma_page", "currentPage", { silent: true })) + "/" + String($c.data.readValue("dma_page", "pageCount", { silent: true })) + ")</span>") : ''); } }];
    $c.util.applyAttrReals(__attrReals);
};

// 런타임 분기 평가 — 공용 $c.util.evalConds (화면은 조건 바인딩 목록만 보유)
// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = function () {
    let binds = [{ id: "if_result", fn: function(){ return (!(String(($c.data.readValue("dma_pageContext", "result", { ctx: true, label: "result" })) == null ? '' : ($c.data.readValue("dma_pageContext", "result", { ctx: true, label: "result" }))).length === 0)); } }];
    $c.util.evalConds(binds);
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = function () {
    let __rowCopies = [{ childId: "ipt_searchRadio", fn: function () { return String(String($c.data.readValue("dma_pageContext", "searchRadio", { silent: true }))); } }];
    $c.data.copyRows(__rowCopies);
};

/**
