*/
scwin.init_datefmt_cal_stdCdGrntEndDd = function () { $c.date.checkCalendarFormat("cal_stdCdGrntEndDd", "yyyyMMdd"); };

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        let std_cd_grnt_start_dd = (String(($c.data.readValue("dma_pageContext", "std_cd_grnt_start_dd", { ctx: true, soft: true, label: "std_cd_grnt_start_dd" })) == null ? '' : ($c.data.readValue("dma_pageContext", "std_cd_grnt_start_dd", { ctx: true, soft: true, label: "std_cd_grnt_start_dd" }))).indexOf('$' + '{') >= 0 ? '' : String(($c.data.readValue("dma_pageContext", "std_cd_grnt_start_dd", { ctx: true, soft: true, label: "std_cd_grnt_start_dd" })) == null ? '' : ($c.data.readValue("dma_pageContext", "std_cd_grnt_start_dd", { ctx: true, soft: true, label: "std_cd_grnt_start_dd" }))));
        let std_cd_grnt_end_dd = (String(($c.data.readValue("dma_pageContext", "std_cd_grnt_end_dd", { ctx: true, soft: true, label: "std_cd_grnt_end_dd" })) == null ? '' : ($c.data.readValue("dma_pageContext", "std_cd_grnt_end_dd", { ctx: true, soft: true, label: "std_cd_grnt_end_dd" }))).indexOf('$' + '{') >= 0 ? '' : String(($c.data.readValue("dma_pageContext", "std_cd_grnt_end_dd", { ctx: true, soft: true, label: "std_cd_grnt_end_dd" })) == null ? '' : ($c.data.readValue("dma_pageContext", "std_cd_grnt_end_dd", { ctx: true, soft: true, label: "std_cd_grnt_end_dd" }))));
        if (std_cd_grnt_start_dd !== "") {
            if (std_cd_grnt_start_dd.length === 8) {
                $c.util.getComponent('cal_stdCdGrntStartDd').setValue($c.date.dateFormat(std_cd_grnt_start_dd));
            } else {
                $c.util.getComponent('cal_stdCdGrntStartDd').setValue(std_cd_grnt_start_dd);
            }
        }
        if (std_cd_grnt_end_dd !== "") {
            if (std_cd_grnt_end_dd.length === 8) {
                $c.util.getComponent('cal_stdCdGrntEndDd').setValue($c.date.dateFormat(std_cd_grnt_end_dd));
            } else {
                $c.util.getComponent('cal_stdCdGrntEndDd').setValue(std_cd_grnt_end_dd);
            }
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf20000p.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { $c.data.recvParamData('dma_pageContext'); };

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin._popupWindow = undefined; scwin.type = undefined;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_datefmt_cal_stdCdGrntStartDd();
        scwin.init_datefmt_cal_stdCdGrntEndDd();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf20000p.onpageload' });
    }
};


