*/
scwin.dataTb_oncellclick = async function (rowIndex, columnIndex, columnId) { try { let dl = $c.util.getComponent('dlt_result'); let r = dl && dl.getRowJSON ? dl.getRowJSON(rowIndex) : null; if (!r) { return; } if (r["mktNm"] !== '14') { await scwin.onPopupCode(r["mktNm"], r["stdCd"]); return; } } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: 'dataTb.oncellclick' }); } };

