/**
 * @method
 * @name scwin.tx_onPopupCode
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_onPopupCode = async function () {
    const sbmOptions = {
        id: "tx_onPopupCode",
        method: "post",
        action: "/srch/srch.do?method=srchPopup",
        ref: "dma_onPopupCodeReq",
        target: "dlt_result=body",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldinf20000p.tx_onPopupCode" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};

/**
 * @method
