        action: "/srch/srch.do?method=srchPopupList",
        ref: "dma_searchReq",
        target: "dlt_result=body",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldinf20000p.tx_fn_search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

// 표준 API 조합으로 새로 작성한 검사 함수
/**
 * @method
 * @name scwin.fn_appDate2
 * @author Inswave
 * @date 2026. 09. 06
 * @param startId endId months
 * @returns
 * @hidden N
*/
scwin.fn_appDate2 = function (startId, endId, months) { try { const __end = $c.date.getServerDateTime(); const __start = $c.date.addMonth(__end, -Number(months || 0)); const __r = function (nm) { return $c.util.getComponent('cal_' + nm) || $c.util.getComponent('ipt_' + nm) || $c.util.getComponent(String(nm)); }; const __s = __r(String(startId)); if (__s && __s.setValue) { __s.setValue(__start); } const __e2 = __r(String(endId)); if (__e2 && __e2.setValue) { __e2.setValue(__end); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'fn_appDate2' }); } };

/**
 * @method
 * @name scwin.dateSetting
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.dateSetting = function () {
    let curDate = (String(($c.data.readValue("dma_pageContext", "curDate", { ctx: true, soft: true, label: "curDate" })) == null ? '' : ($c.data.readValue("dma_pageContext", "curDate", { ctx: true, soft: true, label: "curDate" }))).indexOf('$' + '{') >= 0 ? '' : String(($c.data.readValue("dma_pageContext", "curDate", { ctx: true, soft: true, label: "curDate" })) == null ? '' : ($c.data.readValue("dma_pageContext", "curDate", { ctx: true, soft: true, label: "curDate" }))));
    let curYY = curDate.substring(0, 4);
    let curMM = curDate.substring(4, 6);
    let curDD = curDate.substring(6, 8);
    let intCurYY = Number(curYY);
    let intCurMM = Number(curMM);
    let bfOneYY = "";
    let bfOneMM = "";
    var calMM = intCurMM - 1;
    if (calMM < 0) {
        bfOneYY = intCurYY - 1;
        bfOneMM = 12 + calMM;
    } else {
        bfOneYY = intCurYY;
        bfOneMM = calMM;
    }
    let bfThreeYY = "";
    let bfThreeMM = "";
    var calMM = intCurMM - 3;
    if (calMM < 0) {
        bfThreeYY = intCurYY - 1;
        bfThreeMM = 12 + calMM;
    } else {
        bfThreeYY = intCurYY;
        bfThreeMM = calMM;
    }
    let bfSixYY = "";
    let bfSixMM = "";
    var calMM = intCurMM - 6;
    if (calMM < 0) {
        bfSixYY = intCurYY - 1;
        bfSixMM = 12 + calMM;
    } else {
        bfSixYY = intCurYY;
        bfSixMM = calMM;
    }
    let oneDD = new Date(bfOneYY, bfOneMM, curDD);
    let threeDD = new Date(bfThreeYY, bfThreeMM, curDD);
    let sixDD = new Date(bfSixYY, bfSixMM, curDD);
    if (Number(bfOneMM) < 10) {
        bfOneMM = "0" + bfOneMM;
    }
    if (Number(bfThreeMM) < 10) {
        bfThreeMM = "0" + bfThreeMM;
    }
    if (Number(bfSixMM) < 10) {
        bfSixMM = "0" + bfSixMM;
    }
    let oneD = (Number(oneDD.getMonth()) < 10) ? ("0" + oneDD.getMonth()) : oneDD.getMonth();
    let ThD = (Number(threeDD.getMonth()) < 10) ? ("0" + threeDD.getMonth()) : threeDD.getMonth();
    let SxD = (Number(sixDD.getMonth()) < 10) ? ("0" + sixDD.getMonth()) : sixDD.getMonth();
    let oneDt = (Number(oneDD.getDate()) < 10) ? ("0" + oneDD.getDate()) : oneDD.getDate();
    let ThDt = (Number(threeDD.getDate()) < 10) ? ("0" + threeDD.getDate()) : threeDD.getDate();
    let SxDt = (Number(sixDD.getDate()) < 10) ? ("0" + sixDD.getDate()) : sixDD.getDate();
    let bfOneDate = oneDD.getFullYear() + oneD + oneDt;
    let bfThreeDate = threeDD.getFullYear() + ThD + ThDt;
    let bfSixDate = sixDD.getFullYear() + SxD + SxDt;
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_hdOneDate', bfOneDate) : console.warn('[sdd] hiddenStore 부재: ipt_hdOneDate'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_hdThreeDate', bfThreeDate) : console.warn('[sdd] hiddenStore 부재: ipt_hdThreeDate'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_hdSixDate', bfSixDate) : console.warn('[sdd] hiddenStore 부재: ipt_hdSixDate'));
};


/**
 * @method
 * @name scwin.onPopupCode
 * @author Inswave
 * @date 2026. 09. 06
 * @param type ipt_stdCd
 * @returns
 * @hidden N
*/
scwin.onPopupCode = async function (type, ipt_stdCd) {
    let fm = (document.popup_form || { elements: [] });
    scwin._popupWindow = $c.win.openPopup("/jldinf20000p/jldinf20000p.xml", { id: "winPop", scrollbars: true, resizable: false, width: "1000", height: "670", type: "pageFramePopup" }, ($c.util.getComponent("dma_onPopupCodeReq") ? $c.util.getComponent("dma_onPopupCodeReq").getJSON() : {}));
    if (type === "122") {
        type = "12";
    }
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_stdcdType', type) : console.warn('[sdd] hiddenStore 부재: ipt_stdcdType'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_stdCd', ipt_stdCd) : console.warn('[sdd] hiddenStore 부재: ipt_stdCd'));
    fm.action = "/srch/srch.do?method=srchPopup" + type;

};


/**
 * @method
 * @name scwin.open_corp_cd
 * @author Inswave
 * @date 2026. 09. 06
 * @param item_id item_nm
 * @returns
 * @hidden N
*/
scwin.open_corp_cd = function (item_id, item_nm) {
    formName = (document.JLDINF20000p || { elements: [] });
    fn_popupCorpSearch2(formName, item_id, item_nm);
};


/**
 * @method
 * @name scwin.fn_search
 * @author Inswave
 * @date 2026. 09. 06
 * @param idx
 * @returns
 * @hidden N
*/
scwin.fn_search = async function (idx) {
    let srIdx = $('input[name=ipt_searchRadio]:checked').val();
    let ck_stat_cd = "";
    let ckArr = $('input[name=list_cd3]:checked');
    let statLeng = ckArr.length;
    if (statLeng > 0) {
        for (let i = 0; i < statLeng; i++) {
            ck_stat_cd = ck_stat_cd + ((ck_stat_cd === "") ? "'" + $(ckArr[i]).val() + "'" : ",'" + $(ckArr[i]).val() + "'");
        }
    }
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_listCd', ck_stat_cd) : console.warn('[sdd] hiddenStore 부재: ipt_listCd'));
    let frm = (document.JLDINF20000p || { elements: [] });
    if (idx === '1') {
        $('input[name=pageIndex]').val("1");
    }
    frm.action = "/srch/srch.do?method=srchPopupList";
    frm.target = "_self";
    blockLoading();
    await scwin.tx_fn_search();
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_127_onclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_127_onclick = function (index) { scwin.fn_search(index); };
